import{_ as t,c as n,j as e,a as l,o as r}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第一百二十七章 快乐和痛苦并存","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/127第一百二十七章 快乐和痛苦并存.md","filePath":"meditation/巴利文大藏经/127第一百二十七章 快乐和痛苦并存.md"}'),_={name:"meditation/巴利文大藏经/127第一百二十七章 快乐和痛苦并存.md"};function o(s,a,i,d,p,c){return r(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第一百二十七章-快乐和痛苦并存",tabindex:"-1"},[l("第一百二十七章 快乐和痛苦并存 "),e("a",{class:"header-anchor",href:"#第一百二十七章-快乐和痛苦并存","aria-label":'Permalink to "第一百二十七章 快乐和痛苦并存"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部14相应34经/一向的苦经(界相应/因缘篇/修多罗)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园。有一天，佛陀对出家弟子们说：“弟子们，如果地界、水界、火界、风界（地界、水界、火界、风界解释，见第一百二十四章）只能给众生带来痛苦，只能让众生陷入痛苦，只能让众生体会到痛苦，无法让众生体会到快乐、喜悦，那么世间的众生就不会迷恋、沉迷、贪着地界、水界、火界、风界。",-1),e("p",null,"但是，弟子们，因为地界、水界、火界、风界还能给众生带来快乐、喜悦，还能让众生沉浸在快乐、喜悦之中，还能让众生体会到快乐、喜悦，当众生沉溺在快乐、喜悦之中的时候，就无法体会到地界、水界、火界、风界给自己带来的痛苦，所以世间的众生就会迷恋、沉迷、贪着地界、水界、火界、风界。",-1),e("p",null,"弟子们，如果地界、水界、火界、风界只能给众生带来快乐、喜悦，只能让众生沉浸在快乐、喜悦之中，只能让众生体会到快乐、喜悦，无法让众生体会到痛苦，那么世间的众生就不会厌恶、讨厌、憎恶地界、水界、火界、风界。",-1),e("p",null,"但是，弟子们，因为地界、水界、火界、风界还能给众生带来痛苦，还能让众生陷入痛苦，还能让众生体会到痛苦，当众生堕入痛苦之中的时候，就无法体会到地界、水界、火界、风界给自己带来的快乐、喜悦，所以世间的众生就会厌恶、讨厌、憎恶地界、水界、火界、风界。”",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(_,[["render",o]]);export{u as __pageData,f as default};
